<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><title>Cetak QR Terpilih</title><style>@page{size:A4 portrait;margin:10mm}*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#111}.tools{text-align:right;margin-bottom:15px}.tools button{padding:9px 15px;border:0;border-radius:5px;background:#047857;color:#fff}.heading{text-align:center;margin-bottom:8mm}.heading h1{font-size:14pt;margin:0 0 2mm}.heading p{margin:0;font-size:8pt}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:5mm}.item{height:80mm;padding:5mm;border:1px solid #777;text-align:center;break-inside:avoid}.item img{width:48mm;height:48mm}.item b{display:block;margin-top:2mm;font-size:9pt}.item strong{display:block;margin-top:1.5mm;overflow:hidden;font-size:8pt;white-space:nowrap;text-overflow:ellipsis}.item small{display:block;margin-top:2mm;font-size:6.5pt}@media print{.tools{display:none}}</style></head><body><div class="tools"><button onclick="window.print()">Print Semua QR</button></div><header class="heading"><h1>{{ $schoolSetting->display_name }}</h1><p>QR CODE ASET INVENTARIS · {{ $assets->count() }} aset</p></header><main class="grid">@foreach($assets as $asset)<article class="item"><img src="{{ $asset->qr_data_uri }}" alt="QR {{ $asset->asset_code }}"><b>{{ $asset->asset_code }}</b><strong>{{ $asset->name }}</strong><small>Scan untuk informasi aset</small></article>@endforeach</main><script>window.addEventListener('load',()=>window.print())</script></body></html>
